import{_ as e,c as o,o as a,ag as d}from"./chunks/framework.CyMCuEUM.js";const g=JSON.parse('{"title":"Visual Studio Code 详细指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/development-tools/vscode.md","filePath":"guide/development-tools/vscode.md"}'),r={name:"guide/development-tools/vscode.md"};function l(i,t,n,c,s,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="visual-studio-code-详细指南" tabindex="-1">Visual Studio Code 详细指南 <a class="header-anchor" href="#visual-studio-code-详细指南" aria-label="Permalink to &quot;Visual Studio Code 详细指南&quot;">​</a></h1><p>Visual Studio Code（VS Code）是微软开发的轻量级、高性能的代码编辑器，通过安装插件可以支持Java开发。它以其启动速度快、占用资源少、功能强大和扩展性强而受到开发者的广泛欢迎。</p><h2 id="常用快捷键" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键" aria-label="Permalink to &quot;常用快捷键&quot;">​</a></h2><h3 id="编辑操作" tabindex="-1">编辑操作 <a class="header-anchor" href="#编辑操作" aria-label="Permalink to &quot;编辑操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能描述</th></tr></thead><tbody><tr><td><code>Ctrl + Space</code></td><td>智能代码补全</td></tr><tr><td><code>Ctrl + Shift + Space</code></td><td>参数信息提示</td></tr><tr><td><code>Alt + Shift + F</code></td><td>格式化代码</td></tr><tr><td><code>Ctrl + H</code></td><td>替换</td></tr><tr><td><code>Ctrl + Shift + F</code></td><td>全局搜索</td></tr><tr><td><code>Ctrl + Shift + H</code></td><td>全局替换</td></tr><tr><td><code>F8</code></td><td>跳转到下一个错误或警告</td></tr><tr><td><code>Shift + F8</code></td><td>跳转到上一个错误或警告</td></tr><tr><td><code>Ctrl + .</code></td><td>快速修复/代码操作</td></tr><tr><td><code>Alt + ↑/↓</code></td><td>上下移动当前行</td></tr><tr><td><code>Shift + Alt + ↑/↓</code></td><td>复制当前行到上/下</td></tr><tr><td><code>Ctrl + X</code></td><td>剪切当前行</td></tr><tr><td><code>Ctrl + /</code></td><td>注释/取消注释当前行</td></tr></tbody></table><h3 id="导航操作" tabindex="-1">导航操作 <a class="header-anchor" href="#导航操作" aria-label="Permalink to &quot;导航操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能描述</th></tr></thead><tbody><tr><td><code>Ctrl + P</code></td><td>快速打开文件</td></tr><tr><td><code>Ctrl + G</code></td><td>跳转到指定行</td></tr><tr><td><code>F12</code></td><td>跳转到定义</td></tr><tr><td><code>Alt + F12</code></td><td>查看定义（不跳转）</td></tr><tr><td><code>Ctrl + Shift + O</code></td><td>跳转到符号</td></tr><tr><td><code>Ctrl + Tab</code></td><td>切换到下一个打开的文件</td></tr><tr><td><code>Ctrl + B</code></td><td>显示/隐藏侧边栏</td></tr><tr><td><code>Ctrl + Backtick</code></td><td>显示/隐藏终端</td></tr></tbody></table><h3 id="运行和调试" tabindex="-1">运行和调试 <a class="header-anchor" href="#运行和调试" aria-label="Permalink to &quot;运行和调试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能描述</th></tr></thead><tbody><tr><td><code>F5</code></td><td>开始调试</td></tr><tr><td><code>Ctrl + F5</code></td><td>运行不调试</td></tr><tr><td><code>F10</code></td><td>单步跳过</td></tr><tr><td><code>F11</code></td><td>单步进入</td></tr><tr><td><code>Shift + F11</code></td><td>单步跳出</td></tr><tr><td><code>Shift + F5</code></td><td>停止调试</td></tr><tr><td><code>Ctrl + Shift + D</code></td><td>打开调试视图</td></tr><tr><td><code>F9</code></td><td>切换断点</td></tr></tbody></table><h3 id="窗口和面板" tabindex="-1">窗口和面板 <a class="header-anchor" href="#窗口和面板" aria-label="Permalink to &quot;窗口和面板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能描述</th></tr></thead><tbody><tr><td><code>Ctrl + N</code></td><td>新建文件</td></tr><tr><td><code>Ctrl + W</code></td><td>关闭当前文件</td></tr><tr><td><code>Ctrl + Shift + W</code></td><td>关闭所有文件</td></tr><tr><td><code>Ctrl + ,</code></td><td>打开设置</td></tr><tr><td><code>Ctrl + Shift + P</code></td><td>打开命令面板</td></tr><tr><td><code>Ctrl + \\</code></td><td>分割编辑器</td></tr><tr><td><code>Ctrl + 1/2/3</code></td><td>切换到指定编辑器组</td></tr></tbody></table><h2 id="推荐插件" tabindex="-1">推荐插件 <a class="header-anchor" href="#推荐插件" aria-label="Permalink to &quot;推荐插件&quot;">​</a></h2><h3 id="java开发必备插件" tabindex="-1">Java开发必备插件 <a class="header-anchor" href="#java开发必备插件" aria-label="Permalink to &quot;Java开发必备插件&quot;">​</a></h3><ul><li><strong>Extension Pack for Java</strong>：提供Java开发的核心功能，包括代码补全、调试、重构等</li><li><strong>Spring Boot Extension Pack</strong>：Spring Boot开发的增强功能，包括自动完成、代码片段、验证等</li><li><strong>Maven for Java</strong>：Maven构建工具的支持，包括pom.xml编辑辅助、依赖管理等</li><li><strong>Gradle for Java</strong>：Gradle构建工具的支持</li><li><strong>Debugger for Java</strong>：Java调试功能</li><li><strong>Test Runner for Java</strong>：Java测试运行功能</li></ul><h3 id="效率提升插件" tabindex="-1">效率提升插件 <a class="header-anchor" href="#效率提升插件" aria-label="Permalink to &quot;效率提升插件&quot;">​</a></h3><ul><li><strong>GitLens</strong>：增强Git集成功能，显示代码作者、提交信息等</li><li><strong>Bracket Pair Colorizer</strong>：为括号添加不同颜色，提高代码可读性</li><li><strong>Path Intellisense</strong>：文件路径自动补全</li><li><strong>Live Server</strong>：本地开发服务器，支持热重载</li><li><strong>Todo Tree</strong>：TODO注释导航和管理</li><li><strong>Better Comments</strong>：增强注释功能，支持不同类型的注释高亮</li></ul><h3 id="代码质量插件" tabindex="-1">代码质量插件 <a class="header-anchor" href="#代码质量插件" aria-label="Permalink to &quot;代码质量插件&quot;">​</a></h3><ul><li><strong>SonarLint</strong>：实时代码质量分析</li><li><strong>CheckStyle for Java</strong>：Java代码风格检查</li><li><strong>PMD for Java</strong>：Java代码静态分析</li><li><strong>Error Lens</strong>：将错误和警告直接显示在代码行旁边</li><li><strong>Code Spell Checker</strong>：代码拼写检查</li></ul><h3 id="主题和外观插件" tabindex="-1">主题和外观插件 <a class="header-anchor" href="#主题和外观插件" aria-label="Permalink to &quot;主题和外观插件&quot;">​</a></h3><ul><li><strong>Material Theme</strong>：Material Design风格的主题</li><li><strong>One Dark Pro</strong>：Atom风格的深色主题</li><li><strong>Dracula Official</strong>：Dracula风格的主题</li><li><strong>Fira Code</strong>：支持连字功能的等宽字体</li><li><strong>VSCode Icons</strong>：增强文件和文件夹图标</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><h3 id="编辑器配置" tabindex="-1">编辑器配置 <a class="header-anchor" href="#编辑器配置" aria-label="Permalink to &quot;编辑器配置&quot;">​</a></h3><ol><li><strong>设置主题</strong>：选择适合长时间编程的主题，推荐使用深色主题减少眼部疲劳</li><li><strong>配置字体</strong>：选择等宽字体，如Fira Code（支持连字功能）</li><li><strong>调整字体大小和行高</strong>：根据个人偏好和屏幕分辨率调整</li><li><strong>配置文件关联</strong>：确保Java文件使用正确的语法高亮和编辑器配置</li><li><strong>设置自动保存</strong>：配置编辑器自动保存文件，避免意外丢失更改</li></ol><h3 id="工作区优化" tabindex="-1">工作区优化 <a class="header-anchor" href="#工作区优化" aria-label="Permalink to &quot;工作区优化&quot;">​</a></h3><ol><li><strong>使用多根工作区</strong>：在一个窗口中管理多个相关项目</li><li><strong>使用工作区设置</strong>：为不同项目配置特定的设置</li><li><strong>使用搜索功能</strong>：利用强大的搜索功能快速查找文件、符号和代码片段</li><li><strong>使用代码片段</strong>：创建和使用自定义代码片段，提高编码速度</li><li><strong>使用任务管理</strong>：配置自定义任务，自动化重复操作</li></ol><h3 id="java开发技巧" tabindex="-1">Java开发技巧 <a class="header-anchor" href="#java开发技巧" aria-label="Permalink to &quot;Java开发技巧&quot;">​</a></h3><ol><li><strong>配置JDK</strong>：确保正确设置JDK路径和版本</li><li><strong>配置构建工具</strong>：正确配置Maven或Gradle，以便能够编译和构建项目</li><li><strong>使用代码格式化</strong>：配置和使用Java代码格式化规则，保持代码风格一致性</li><li><strong>使用代码分析</strong>：利用内置的代码分析工具发现潜在问题</li><li><strong>使用调试工具</strong>：熟悉和使用调试工具，提高问题排查效率</li></ol><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><ol><li><strong>关闭不必要的插件</strong>：只启用必要的插件，减少资源占用</li><li><strong>配置文件排除</strong>：排除大型二进制文件和生成文件，提高搜索和索引性能</li><li><strong>清理工作区</strong>：定期清理未使用的文件和项目</li><li><strong>调整内存分配</strong>：根据需要调整VSCode的内存分配</li></ol><h3 id="自定义配置" tabindex="-1">自定义配置 <a class="header-anchor" href="#自定义配置" aria-label="Permalink to &quot;自定义配置&quot;">​</a></h3><ol><li><strong>自定义快捷键</strong>：根据个人习惯修改快捷键配置</li><li><strong>自定义代码模板</strong>：创建符合个人或团队编码规范的代码模板</li><li><strong>自定义用户片段</strong>：创建常用代码块的用户片段</li><li><strong>创建工作区配置</strong>：为不同类型的项目创建和保存特定的工作区配置</li></ol><h2 id="emmet在vscode中的使用" tabindex="-1">Emmet在VSCode中的使用 <a class="header-anchor" href="#emmet在vscode中的使用" aria-label="Permalink to &quot;Emmet在VSCode中的使用&quot;">​</a></h2><p>VSCode内置了对Emmet的支持，可以直接使用Emmet语法来快速编写HTML和CSS代码。</p><h3 id="基本使用方法" tabindex="-1">基本使用方法 <a class="header-anchor" href="#基本使用方法" aria-label="Permalink to &quot;基本使用方法&quot;">​</a></h3><ol><li><strong>输入Emmet缩写</strong>：在HTML或CSS文件中输入Emmet缩写表达式</li><li><strong>展开缩写</strong>：按下<code>Tab</code>键或<code>Enter</code>键展开缩写</li><li><strong>示例</strong>：输入<code>div&gt;p*3</code>，然后按下<code>Tab</code>键，将展开为嵌套的div和三个p标签（HTML标签将显示为<code>&amp;lt;div&amp;gt;&amp;lt;p&amp;gt;&amp;lt;/p&amp;gt;&amp;lt;p&amp;gt;&amp;lt;/p&amp;gt;&amp;lt;p&amp;gt;&amp;lt;/p&amp;gt;&amp;lt;/div&amp;gt;</code>）</li></ol><h3 id="vscode中emmet的特殊功能" tabindex="-1">VSCode中Emmet的特殊功能 <a class="header-anchor" href="#vscode中emmet的特殊功能" aria-label="Permalink to &quot;VSCode中Emmet的特殊功能&quot;">​</a></h3><h4 id="_1-快速生成html结构" tabindex="-1">1. 快速生成HTML结构 <a class="header-anchor" href="#_1-快速生成html结构" aria-label="Permalink to &quot;1. 快速生成HTML结构&quot;">​</a></h4><ul><li><strong>生成完整HTML文档</strong>：输入<code>!</code>然后按<code>Tab</code>，生成标准HTML5模板（HTML标签将显示为实体编码形式，如<code>&amp;lt;!DOCTYPE html&amp;gt;</code>等）</li><li><strong>生成带lang属性的HTML</strong>：输入<code>!+lang:zh-CN</code>然后按<code>Tab</code>，生成中文HTML文档（HTML标签将显示为实体编码形式）</li></ul><h4 id="_2-代码片段选择器" tabindex="-1">2. 代码片段选择器 <a class="header-anchor" href="#_2-代码片段选择器" aria-label="Permalink to &quot;2. 代码片段选择器&quot;">​</a></h4><ul><li>当展开的结果有多个选项时，VSCode会显示选择器让你选择所需的结果</li><li>按下<code>Ctrl+Space</code>可以在输入过程中显示可用的Emmet建议</li></ul><h4 id="_3-emmet的css支持" tabindex="-1">3. Emmet的CSS支持 <a class="header-anchor" href="#_3-emmet的css支持" aria-label="Permalink to &quot;3. Emmet的CSS支持&quot;">​</a></h4><ul><li>在CSS文件中输入CSS缩写后按<code>Tab</code>键展开</li><li>示例：输入<code>w100+p20+m10</code>，展开为三个CSS属性声明</li></ul><h4 id="_4-在不同文件类型中使用emmet" tabindex="-1">4. 在不同文件类型中使用Emmet <a class="header-anchor" href="#_4-在不同文件类型中使用emmet" aria-label="Permalink to &quot;4. 在不同文件类型中使用Emmet&quot;">​</a></h4><p>VSCode允许在JavaScript、TypeScript等文件中使用Emmet缩写，需要通过设置启用：</p><ol><li>打开设置（<code>Ctrl+,</code>）</li><li>搜索&quot;emmet include languages&quot;</li><li>点击&quot;添加项&quot;，在&quot;项&quot;中输入文件类型（如<code>javascript</code>），在&quot;值&quot;中输入<code>html</code></li></ol><h4 id="_5-自定义emmet配置" tabindex="-1">5. 自定义Emmet配置 <a class="header-anchor" href="#_5-自定义emmet配置" aria-label="Permalink to &quot;5. 自定义Emmet配置&quot;">​</a></h4><p>VSCode允许自定义Emmet的行为：</p><ol><li>打开设置（<code>Ctrl+,</code>）</li><li>搜索&quot;emmet&quot;</li><li>可以配置以下选项： <ul><li><code>Emmet: Trigger Expansion On Tab</code>：是否在按Tab键时展开Emmet缩写</li><li><code>Emmet: Show Suggestions As Snippets</code>：是否将Emmet建议显示为代码片段</li><li><code>Emmet: Preferences</code>：自定义Emmet首选项</li></ul></li></ol><h4 id="_6-高级emmet功能" tabindex="-1">6. 高级Emmet功能 <a class="header-anchor" href="#_6-高级emmet功能" aria-label="Permalink to &quot;6. 高级Emmet功能&quot;">​</a></h4><ul><li><strong>快速包装代码</strong>：选中要包装的代码，按下<code>Ctrl+Shift+P</code>，输入&quot;Emmet: Wrap with Abbreviation&quot;，然后输入包装的缩写</li><li><strong>使用Emmet的缩写预览</strong>：启用<code>Emmet: Show Abbreviation Suggestions</code>设置，可以预览Emmet缩写的展开结果</li></ul><h3 id="实用emmet技巧在vscode中" tabindex="-1">实用Emmet技巧在VSCode中 <a class="header-anchor" href="#实用emmet技巧在vscode中" aria-label="Permalink to &quot;实用Emmet技巧在VSCode中&quot;">​</a></h3><ol><li><strong>快速创建列表</strong>：输入<code>ul&gt;li*5{item $}</code>然后按<code>Tab</code>，生成5个带编号的列表项（HTML标签将显示为<code>&amp;lt;ul&amp;gt;&amp;lt;li&amp;gt;item 1&amp;lt;/li&amp;gt;...&amp;lt;/ul&amp;gt;</code>形式）</li><li><strong>创建表格</strong>：输入<code>table&gt;thead&gt;tr&gt;th*3{Header $}^tbody&gt;tr*2&gt;td*3{$}</code>然后按<code>Tab</code>，生成一个3列2行的表格（HTML标签将显示为实体编码形式）</li><li><strong>生成响应式布局</strong>：输入<code>div.container&gt;div.row&gt;div.col-md-6*2</code>然后按<code>Tab</code>，生成Bootstrap风格的响应式布局（HTML标签将显示为实体编码形式）</li><li><strong>快速创建表单</strong>：输入<code>form&gt;div.form-group*3&gt;label{${label $}}+input[type=&quot;text&quot; name=&quot;field$&quot; placeholder=&quot;请输入${label $}&quot;]</code>然后按<code>Tab</code>，生成表单组（HTML标签将显示为实体编码形式）</li></ol><p>通过结合VSCode强大的编辑功能和Emmet的高效语法，可以显著提高前端开发的效率。掌握Emmet在VSCode中的使用方法，可以让你的编码速度提升数倍。</p><blockquote><p>注意：详细的Emmet语法规则，请参考<a href="./emmet.html">Emmet语法详解</a>文档。</p></blockquote><p>VSCode作为一个轻量级但功能强大的代码编辑器，通过插件系统可以成为一个高效的Java开发环境。通过合理配置和使用VSCode的功能和插件，可以显著提高Java开发的效率和质量。</p>',55)])])}const u=e(r,[["render",l]]);export{g as __pageData,u as default};
